function getStateByGstin(gstin) {
  const clean = String(gstin || "").trim().toUpperCase();
  if (clean.length < 2) return "";
  const code = clean.slice(0, 2);
  return GST_STATE_CODES[code] || "";
}

function openInvoicePreviewModal(previewData = null, options = {}) {
  const preview = previewData || buildInvoicePreviewData() || sampleInvoicePreviewData();
  if (!preview) return;
  document.getElementById("invoicePreviewModal")?.remove();

  const business = preview.business || state.businessSettings || defaultBusinessSettings();
  let currentFormat = options.printerType || business.printerType || "a4";
  if (currentFormat === "regular") currentFormat = "a4";
  let currentA4Template = options.a4Template || business.a4Template || "modern";
  let currentThermalTemplate = options.thermalTemplate || business.thermalTemplate || "retail";
  let currentThermalWidth = options.thermalWidth || business.thermalWidth || "80mm";

  function getTemplateOptionsHtml(format) {
    if (format === "thermal") {
      return `
        <option value="retail" ${currentThermalTemplate === "retail" ? "selected" : ""}>Retail Supermarket</option>
        <option value="boutique" ${currentThermalTemplate === "boutique" ? "selected" : ""}>Modern Boutique / Cafe</option>
        <option value="detailed" ${currentThermalTemplate === "detailed" ? "selected" : ""}>GST Detailed Roll</option>
      `;
    }
    return `
      <option value="modern" ${currentA4Template === "modern" ? "selected" : ""}>Modern Accent</option>
      <option value="classic" ${currentA4Template === "classic" ? "selected" : ""}>Classic GST Boxed</option>
      <option value="minimal" ${currentA4Template === "minimal" ? "selected" : ""}>Minimalist Monochrome</option>
      <option value="compact" ${currentA4Template === "compact" ? "selected" : ""}>Compact Wholesale</option>
    `;
  }

  const backdrop = document.createElement("div");
  backdrop.className = "modal-backdrop invoice-preview-backdrop";
  backdrop.id = "invoicePreviewModal";
  backdrop.innerHTML = `
    <section class="invoice-preview-modal ${currentFormat === "thermal" ? "is-thermal" : "is-a4"}" role="dialog" aria-modal="true" aria-label="Invoice preview">
      <header>
        <div class="preview-header-left">
          <h2>${escapeHtml(preview.previewTitle || "Invoice Preview")}</h2>
          <div class="preview-controls-bar">
            <label class="preview-control-item">
              <span>Format:</span>
              <select id="previewFormatSelect" class="form-input">
                <option value="a4" ${currentFormat === "a4" ? "selected" : ""}>📄 A4 / Full Page</option>
                <option value="thermal" ${currentFormat === "thermal" ? "selected" : ""}>🧾 Thermal POS Roll</option>
              </select>
            </label>
            <label class="preview-control-item">
              <span>Template:</span>
              <select id="previewTemplateSelect" class="form-input">
                ${getTemplateOptionsHtml(currentFormat)}
              </select>
            </label>
            <label class="preview-control-item ${currentFormat === "thermal" ? "" : "hidden"}" id="previewWidthLabel">
              <span>Roll:</span>
              <select id="previewWidthSelect" class="form-input">
                <option value="80mm" ${currentThermalWidth === "80mm" ? "selected" : ""}>80mm (3")</option>
                <option value="58mm" ${currentThermalWidth === "58mm" ? "selected" : ""}>58mm (2")</option>
              </select>
            </label>
          </div>
        </div>
        <div class="preview-header-actions">
          <button class="secondary-button" type="button" data-preview-whatsapp style="display:inline-flex;align-items:center;gap:6px;background:rgba(37,211,102,0.1);color:#128c7e;border-color:rgba(37,211,102,0.3);font-weight:600;"><svg class="gi-icon" style="width:14px;height:14px;fill:currentColor;"><use href="#gi-whatsapp"></use></svg> WhatsApp</button>
          <button class="secondary-button" type="button" data-preview-pdf>Export PDF</button>
          <button class="primary-button square" type="button" data-preview-print style="height:34px;padding:0 14px;">Print</button>
          <button class="close-button" type="button" data-preview-close>&times;</button>
        </div>
      </header>
      <div class="invoice-preview-paper ${currentFormat === "thermal" ? `paper-thermal width-${currentThermalWidth}` : `paper-a4 template-${currentA4Template}`}">
        ${invoicePreviewMarkup(preview, {
          printerType: currentFormat,
          a4Template: currentA4Template,
          thermalTemplate: currentThermalTemplate,
          thermalWidth: currentThermalWidth
        })}
      </div>
    </section>
  `;
  document.body.append(backdrop);

  const modalSection = backdrop.querySelector(".invoice-preview-modal");
  const paperEl = backdrop.querySelector(".invoice-preview-paper");
  const formatSelect = backdrop.querySelector("#previewFormatSelect");
  const templateSelect = backdrop.querySelector("#previewTemplateSelect");
  const widthSelect = backdrop.querySelector("#previewWidthSelect");
  const widthLabel = backdrop.querySelector("#previewWidthLabel");

  function reRenderPaper() {
    modalSection.classList.toggle("is-thermal", currentFormat === "thermal");
    modalSection.classList.toggle("is-a4", currentFormat !== "thermal");
    paperEl.className = `invoice-preview-paper ${currentFormat === "thermal" ? `paper-thermal width-${currentThermalWidth}` : `paper-a4 template-${currentA4Template}`}`;
    paperEl.innerHTML = invoicePreviewMarkup(preview, {
      printerType: currentFormat,
      a4Template: currentA4Template,
      thermalTemplate: currentThermalTemplate,
      thermalWidth: currentThermalWidth
    });
  }

  formatSelect?.addEventListener("change", () => {
    currentFormat = formatSelect.value;
    templateSelect.innerHTML = getTemplateOptionsHtml(currentFormat);
    if (widthLabel) widthLabel.classList.toggle("hidden", currentFormat !== "thermal");
    reRenderPaper();
  });

  templateSelect?.addEventListener("change", () => {
    if (currentFormat === "thermal") {
      currentThermalTemplate = templateSelect.value;
    } else {
      currentA4Template = templateSelect.value;
    }
    reRenderPaper();
  });

  widthSelect?.addEventListener("change", () => {
    currentThermalWidth = widthSelect.value;
    reRenderPaper();
  });

  backdrop.querySelector("[data-preview-close]")?.addEventListener("click", () => backdrop.remove());
  backdrop.querySelector("[data-preview-whatsapp]")?.addEventListener("click", () => {
    openWhatsAppShareModal(preview, (preview.documentTitle || "").toLowerCase().includes("purchase") ? "purchase" : "sale");
  });
  backdrop.querySelector("[data-preview-print]")?.addEventListener("click", () => {
    if (currentFormat === "thermal") {
      document.body.classList.add("invoice-thermal-print-mode", `thermal-print-${currentThermalWidth}`);
    } else {
      document.body.classList.add("invoice-a4-print-mode");
    }
    window.print();
  });
  window.addEventListener("afterprint", () => {
    document.body.classList.remove("invoice-thermal-print-mode", "thermal-print-80mm", "thermal-print-58mm", "invoice-a4-print-mode");
  }, { once: false });
  backdrop.querySelector("[data-preview-pdf]")?.addEventListener("click", async () => {
    const paperEl = backdrop.querySelector(".invoice-preview-paper");
    if (!paperEl) return;
    const styles = `<style>${Array.from(document.styleSheets).map((sheet) => {
      try { return Array.from(sheet.cssRules).map((rule) => rule.cssText).join('\n'); }
      catch { return ''; }
    }).join('\n')}</style>`;
    const htmlContent = `<!DOCTYPE html><html><head><meta charset="utf-8">${styles}<style>body{background:#fff;padding:20px;font-family:system-ui,-apple-system,sans-serif;}</style></head><body>${paperEl.innerHTML}</body></html>`;
    const defaultFilename = `${(preview.documentTitle || "document").toLowerCase().replace(/\s+/g, "_")}_${preview.invoiceNo || "doc"}.pdf`;
    try {
      if (window.giApp?.exportPdf) {
        const res = await window.giApp.exportPdf({ htmlContent, defaultFilename });
        if (res?.success) {
          showToast(`PDF exported: ${res.filePath.split(/[\\/]/).pop()}`);
        } else if (!res?.canceled) {
          showToast("PDF export was cancelled or failed.");
        }
      } else {
        window.print();
      }
    } catch (e) {
      showToast(`PDF export failed: ${e.message}`);
    }
  });
  backdrop.addEventListener("click", (event) => {
    if (event.target === backdrop) backdrop.remove();
  });
}

function buildInvoicePreviewData() {
  const form = elements.featureView.querySelector("#transactionEditorForm");
  if (!form) return null;
  const business = state.businessSettings || defaultBusinessSettings();
  const editorType = getTransactionEditorType();
  const party = getSelectedTransactionParty();
  const rows = [...elements.featureView.querySelectorAll("#transactionRows tr")]
    .map((row, index) => {
      const item = getSelectedTransactionItem(row);
      const qty = Number(row.querySelector('[name="qty"]')?.value || 0);
      const price = Number(row.querySelector('[name="price"]')?.value || 0);
      const discount = Number(row.querySelector('[name="discount"]')?.value || 0);
      const taxRate = parseTaxRate(row.querySelector('[name="tax"]')?.value || "");
      const taxable = Math.max(0, qty * price - discount);
      const tax = taxable * taxRate / 100;
      return {
        index: index + 1,
        item: row.querySelector('[name="item"]')?.value || "",
        description: row.querySelector('[name="description"]')?.value || "",
        hsnSac: item?.hsnSac || "",
        qty,
        unit: row.querySelector('[name="unit"]')?.value || "",
        price,
        discount,
        taxRate,
        tax,
        total: taxable + tax,
      };
    })
    .filter((row) => row.item || row.qty || row.price);
  return {
    editorType,
    previewTitle: transactionEditorMeta(editorType).previewTitle,
    documentTitle: transactionEditorMeta(editorType).documentTitle,
    business,
    party,
    rows,
    invoiceNo: elements.featureView.querySelector('[name="invoiceNo"]')?.value || "Auto",
    date: elements.featureView.querySelector('[name="invoiceDate"]')?.value || "",
    validUntil: editorType === "estimate" ? elements.featureView.querySelector('[name="dueDate"]')?.value || "" : "",
    address: elements.featureView.querySelector('[name="address"]')?.value || "",
    placeOfSupply: elements.featureView.querySelector('[name="state"]')?.value || "",
    customFields: customFieldsForModule(editorType).map((field) => ({
      ...field,
      value: customFieldValue(field, collectCustomFieldValues(editorType)),
    })).filter((field) => field.showOnPrint && (field.fieldType === "checkbox" ? field.value : String(field.value || "").trim())),
    description: elements.featureView.querySelector('[name="invoiceDescription"]')?.value || "",
    attachments: editorAttachmentNames(),
    subtotal: Number(elements.featureView.querySelector("#editorSubtotal")?.textContent || 0),
    discount: Number(elements.featureView.querySelector("#editorDiscountTotal")?.textContent || 0),
    cgst: Number(elements.featureView.querySelector("#editorCgstTotal")?.textContent || 0),
    sgst: Number(elements.featureView.querySelector("#editorSgstTotal")?.textContent || 0),
    igst: Number(elements.featureView.querySelector("#editorIgstTotal")?.textContent || 0),
    total: Number(elements.featureView.querySelector("#editorGrandTotal")?.value || 0),
  };
}

function amountInIndianWords(num) {
  num = Number(num || 0);
  if (isNaN(num) || num <= 0) return "Zero Rupees Only";
  const a = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
  const b = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];

  function inWords(n) {
    if (n === 0) return "";
    if (n < 20) return a[n];
    if (n < 100) return b[Math.floor(n / 10)] + (n % 10 !== 0 ? " " + a[n % 10] : "");
    if (n < 1000) return a[Math.floor(n / 100)] + " Hundred" + (n % 100 !== 0 ? " " + inWords(n % 100) : "");
    return "";
  }

  const integerPart = Math.floor(num);
  const decimalPart = Math.round((num - integerPart) * 100);

  let result = "";
  const crore = Math.floor(integerPart / 10000000);
  let rem = integerPart % 10000000;
  const lakh = Math.floor(rem / 100000);
  rem = rem % 100000;
  const thousand = Math.floor(rem / 1000);
  rem = rem % 1000;
  const hundreds = rem;

  if (crore > 0) result += (inWords(crore) + " Crore ");
  if (lakh > 0) result += (inWords(lakh) + " Lakh ");
  if (thousand > 0) result += (inWords(thousand) + " Thousand ");
  if (hundreds > 0) result += (inWords(hundreds) + " ");

  result = (result.trim() ? result.trim() + " Rupees" : "");
  if (decimalPart > 0) {
    const paiseStr = inWords(decimalPart) + " Paise";
    result = result ? (result + " and " + paiseStr) : (paiseStr);
  }
  return result ? (result + " Only") : "Zero Rupees Only";
}

function generateUpiQrSvg(text, displaySize = 76) {
  const exp = new Uint8Array(512);
  const log = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    exp[i] = x;
    exp[i + 255] = x;
    log[x] = i;
    x = (x << 1) ^ (x >= 128 ? 0x11d : 0);
  }

  function gfMul(a, b) {
    return a === 0 || b === 0 ? 0 : exp[log[a] + log[b]];
  }

  function rsPoly(numEc) {
    let poly = [1];
    for (let i = 0; i < numEc; i++) {
      const next = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= gfMul(poly[j], exp[i]);
        next[j + 1] ^= poly[j];
      }
      poly = next;
    }
    return poly;
  }

  function rsEncode(data, numEc) {
    const gen = rsPoly(numEc);
    const res = new Uint8Array(numEc);
    for (let i = 0; i < data.length; i++) {
      const factor = data[i] ^ res[0];
      for (let j = 0; j < numEc - 1; j++) {
        res[j] = res[j + 1] ^ gfMul(gen[j + 1], factor);
      }
      res[numEc - 1] = gfMul(gen[numEc], factor);
    }
    return res;
  }

  const bytes = new TextEncoder().encode(text);
  let version = 3;
  let totalData = 55;
  let numEc = 15;
  if (bytes.length > 53) {
    version = 4;
    totalData = 80;
    numEc = 20;
  }

  const dataBits = [];
  function pushBits(val, len) {
    for (let i = len - 1; i >= 0; i--) dataBits.push((val >> i) & 1);
  }

  pushBits(4, 4);
  pushBits(bytes.length, 8);
  for (const b of bytes) pushBits(b, 8);

  const bitCapacity = totalData * 8;
  const termLen = Math.min(4, bitCapacity - dataBits.length);
  for (let i = 0; i < termLen; i++) dataBits.push(0);
  while (dataBits.length % 8 !== 0) dataBits.push(0);

  const dataBytes = [];
  for (let i = 0; i < dataBits.length; i += 8) {
    let byte = 0;
    for (let b = 0; b < 8; b++) byte = (byte << 1) | dataBits[i + b];
    dataBytes.push(byte);
  }
  let padToggle = false;
  while (dataBytes.length < totalData) {
    dataBytes.push(padToggle ? 0x11 : 0xec);
    padToggle = !padToggle;
  }

  const ecBytes = rsEncode(dataBytes, numEc);
  const finalCodewords = [...dataBytes, ...ecBytes];
  const size = 17 + version * 4;
  const matrix = Array.from({ length: size }, () => Array(size).fill(null));

  function setFinder(row, col) {
    for (let r = 0; r < 7; r++) {
      for (let c = 0; c < 7; c++) {
        const isDark = r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4);
        matrix[row + r][col + c] = isDark ? 1 : 0;
      }
    }
  }

  setFinder(0, 0);
  setFinder(0, size - 7);
  setFinder(size - 7, 0);

  for (let i = 0; i < 8; i++) {
    if (size - 8 + i < size) {
      matrix[7][size - 8 + i] = 0;
      matrix[size - 8 + i][7] = 0;
    }
    if (i < 8) {
      matrix[7][i] = 0;
      matrix[i][7] = 0;
    }
  }
  for (let i = 8; i < size - 8; i++) {
    matrix[6][i] = i % 2 === 0 ? 1 : 0;
    matrix[i][6] = i % 2 === 0 ? 1 : 0;
  }

  const alignPos = version === 3 ? 22 : 26;
  for (let r = -2; r <= 2; r++) {
    for (let c = -2; c <= 2; c++) {
      const isDark = Math.abs(r) === 2 || Math.abs(c) === 2 || (r === 0 && c === 0);
      matrix[alignPos + r][alignPos + c] = isDark ? 1 : 0;
    }
  }

  matrix[size - 8][8] = 1;

  const formatBits = [1, 1, 1, 0, 1, 1, 1, 1, 1, 0, 0, 0, 1, 0, 0];
  for (let i = 0; i < 6; i++) matrix[8][i] = formatBits[i];
  matrix[8][7] = formatBits[6];
  matrix[8][8] = formatBits[7];
  matrix[7][8] = formatBits[8];
  for (let i = 9; i < 15; i++) matrix[14 - i][8] = formatBits[i];

  for (let i = 0; i < 8; i++) matrix[size - 1 - i][8] = formatBits[i];
  for (let i = 8; i < 15; i++) matrix[8][size - 15 + i] = formatBits[i];

  let bitIdx = 0;
  const allBits = [];
  for (const cw of finalCodewords) {
    for (let b = 7; b >= 0; b--) allBits.push((cw >> b) & 1);
  }

  let right = size - 1;
  let upward = true;
  while (right > 0) {
    if (right === 6) right--;
    for (let step = 0; step < size; step++) {
      const r = upward ? (size - 1 - step) : step;
      for (let c = right; c > right - 2; c--) {
        if (matrix[r][c] === null) {
          const bit = bitIdx < allBits.length ? allBits[bitIdx++] : 0;
          const mask = (r + c) % 2 === 0;
          matrix[r][c] = (bit ^ (mask ? 1 : 0));
        }
      }
    }
    upward = !upward;
    right -= 2;
  }

  const cellSize = (displaySize / size).toFixed(2);
  let rects = "";
  for (let r = 0; r < size; r++) {
    for (let c = 0; c < size; c++) {
      if (matrix[r][c] === 1) {
        rects += `<rect x="${(c * cellSize).toFixed(1)}" y="${(r * cellSize).toFixed(1)}" width="${cellSize}" height="${cellSize}" fill="#0f172a"/>`;
      }
    }
  }
  return `<svg viewBox="0 0 ${displaySize} ${displaySize}" width="${displaySize}" height="${displaySize}" xmlns="http://www.w3.org/2000/svg"><rect width="${displaySize}" height="${displaySize}" fill="#ffffff"/>${rects}</svg>`;
}

