  const purchases = totals.invoices.filter((inv) => invoiceStatusKey(inv) !== "cancelled");
  const purchaseIds = new Set(purchases.map((inv) => inv.id));
  const lines = (state.invoiceItems || []).filter((l) => purchaseIds.has(l.invoiceId));

  const slabs = new Map();
