function renderCurrentList() {
  if (currentView === "home") return;
  const query = globalSearchQuery();
  let rows = [];
  let head = [];

  if (currentView === "parties") {
    head = ["Party", "Notes", "Created"];
    rows = state.parties.map((party) => [party.name, party.notes || "-", formatDate(party.createdAt)]);
  } else if (currentView === "items") {
    head = ["Item", "Unit", "Current Stock", "Purchase Price", "Sale Price", "Created"];
    rows = (state.items || []).filter((item) => !isExpenseItem(item)).map((item) => [
      item.name,
      item.unit || "-",
      Number(item.currentStock || 0),
      formatCurrency(item.purchasePrice || 0),
      formatCurrency(item.salePrice || 0),
      formatDate(item.createdAt),
    ]);
  } else if (currentView === "reports") {
    head = ["Report", "Value"];
    rows = [
      ["Sale Report", formatCurrency(totalFor("sale"))],
      ["Purchase Report", formatCurrency(totalFor("purchase"))],
      ["Receivable", elements.receivableTotal.textContent],
      ["Payable", elements.payableTotal.textContent],
      ["Parties", state.parties.length],
      ["Items", state.items.length],
    ];
  } else {
    const type = currentView === "purchases" ? "purchase" : currentView === "sales" ? "sale" : "";
    head = ["Date", "Type", "Party", "Item", "Status", "Amount", "Notes"];
    rows = state.transactions
      .filter((entry) => !type || entry.type === type)
      .map((entry) => [
        formatDate(entry.date),
        entry.type,
        entry.party,
        entry.item,
        entry.status,
        formatCurrency(entry.amount),
        entry.notes || "-",
      ]);
  }

  if (query) {
    rows = rows.filter((row) => row.join(" ").toLowerCase().includes(query));
  }

  elements.tableHead.innerHTML = `<tr>${head.map((cell) => `<th>${cell}</th>`).join("")}</tr>`;
  elements.tableBody.innerHTML = rows
    .map((row) => `<tr>${row.map((cell) => `<td>${escapeHtml(String(cell))}</td>`).join("")}</tr>`)
    .join("");
  elements.emptyTable.classList.toggle("hidden", rows.length > 0);
}

function globalSearchQuery() {
  return String(elements.searchInput?.value || "").trim().toLowerCase();
}

// ── Dashboard Smooth Animated Graph Engine ──────────────────────────────────
let dashboardChartState = {
  frameId: 0,
  isAnimating: false,
  startTime: 0,
  duration: 650,
  activePeriod: "This Month",
  fromSalesValues: [],
  targetSalesValues: [],
  currentSalesValues: [],
  fromPurchaseValues: [],
  targetPurchaseValues: [],
  currentPurchaseValues: [],
  get fromValues() { return this.fromSalesValues; },
  set fromValues(v) { this.fromSalesValues = v; },
  get targetValues() { return this.targetSalesValues; },
  set targetValues(v) { this.targetSalesValues = v; },
  get currentValues() { return this.currentSalesValues; },
  set currentValues(v) { this.currentSalesValues = v; },
  labels: [],
  title: "",
  maxValue: 0,
  niceMax: 1,
  mouseX: -1,
  mouseY: -1,
  isHovered: false,
  hoverOpacity: 0,
  listenersAttached: false,
};

function resampleChartArray(source, targetLen) {
  if (!source || !source.length) return new Array(targetLen).fill(0);
  if (source.length === targetLen) return [...source];
  const result = new Array(targetLen);
  for (let i = 0; i < targetLen; i++) {
    const srcIdx = (i / Math.max(1, targetLen - 1)) * (source.length - 1);
    const low = Math.floor(srcIdx);
    const high = Math.min(source.length - 1, Math.ceil(srcIdx));
    const frac = srcIdx - low;
    result[i] = (source[low] || 0) * (1 - frac) + (source[high] || 0) * frac;
  }
  return result;
}

function ensureChartCanvasListeners() {
  const canvas = elements.salesChart;
  if (!canvas || dashboardChartState.listenersAttached) return;
  dashboardChartState.listenersAttached = true;

  canvas.addEventListener("mousemove", (e) => {
    const rect = canvas.getBoundingClientRect();
    dashboardChartState.mouseX = e.clientX - rect.left;
    dashboardChartState.mouseY = e.clientY - rect.top;
    dashboardChartState.isHovered = true;
    startChartRenderLoop();
  });

  canvas.addEventListener("mouseleave", () => {
    dashboardChartState.isHovered = false;
    startChartRenderLoop();
  });
}

function scheduleDashboardChartDraw() {
  const canvas = elements.salesChart;
  if (!canvas || elements.homeView?.classList.contains("hidden")) return;

  const period = document.getElementById("periodSelect")?.value || "This Month";
  const series = dashboardSeries(period);
  const targetSales = series.salesValues;
  const targetPurchases = series.purchaseValues;

  const maxVal = Math.max(...targetSales, ...targetPurchases, 0);
  const niceMax = niceChartMax(maxVal);

  const salePeriodTotal = targetSales.reduce((sum, v) => sum + v, 0);
  const purchasePeriodTotal = targetPurchases.reduce((sum, v) => sum + v, 0);

  if (elements.saleTotal) {
    elements.saleTotal.dataset.actualValue = formatCurrency(salePeriodTotal);
  }
  if (elements.purchaseTotal) {
    elements.purchaseTotal.dataset.actualValue = formatCurrency(purchasePeriodTotal);
  }
  updateDashboardPrivacyAmounts();

  const periodChanged = dashboardChartState.activePeriod !== period;
  dashboardChartState.activePeriod = period;
  dashboardChartState.labels = series.labels;
  dashboardChartState.title = series.title;
  dashboardChartState.maxValue = maxVal;
  dashboardChartState.niceMax = niceMax;

  if (dashboardChartState.currentSalesValues.length === targetSales.length && !periodChanged) {
    dashboardChartState.fromSalesValues = [...dashboardChartState.currentSalesValues];
  } else if (dashboardChartState.currentSalesValues.length > 0 && periodChanged) {
    dashboardChartState.fromSalesValues = resampleChartArray(dashboardChartState.currentSalesValues, targetSales.length);
  } else {
    dashboardChartState.fromSalesValues = new Array(targetSales.length).fill(0);
    dashboardChartState.currentSalesValues = [...dashboardChartState.fromSalesValues];
  }

  if (dashboardChartState.currentPurchaseValues.length === targetPurchases.length && !periodChanged) {
    dashboardChartState.fromPurchaseValues = [...dashboardChartState.currentPurchaseValues];
  } else if (dashboardChartState.currentPurchaseValues.length > 0 && periodChanged) {
    dashboardChartState.fromPurchaseValues = resampleChartArray(dashboardChartState.currentPurchaseValues, targetPurchases.length);
  } else {
    dashboardChartState.fromPurchaseValues = new Array(targetPurchases.length).fill(0);
    dashboardChartState.currentPurchaseValues = [...dashboardChartState.fromPurchaseValues];
  }

  dashboardChartState.targetSalesValues = [...targetSales];
  dashboardChartState.targetPurchaseValues = [...targetPurchases];
  dashboardChartState.startTime = performance.now();
  dashboardChartState.isAnimating = true;

  ensureChartCanvasListeners();
  startChartRenderLoop();
}

function drawChart() {
  scheduleDashboardChartDraw();
}

function startChartRenderLoop() {
  if (dashboardChartState.frameId) cancelAnimationFrame(dashboardChartState.frameId);

  function frame(now) {
    dashboardChartState.frameId = 0;
    const canvas = elements.salesChart;
    if (!canvas || elements.homeView?.classList.contains("hidden")) return;

    let needsNext = false;

    if (dashboardChartState.isAnimating) {
      const elapsed = now - dashboardChartState.startTime;
      const progress = Math.min(1, Math.max(0, elapsed / dashboardChartState.duration));
      const ease = 1 - Math.pow(1 - progress, 3);

      const fromS = dashboardChartState.fromSalesValues;
      const toS = dashboardChartState.targetSalesValues;
      dashboardChartState.currentSalesValues = toS.map((targetVal, i) => {
        const fromVal = fromS[i] ?? 0;
        return fromVal + (targetVal - fromVal) * ease;
      });

      const fromP = dashboardChartState.fromPurchaseValues;
      const toP = dashboardChartState.targetPurchaseValues;
      dashboardChartState.currentPurchaseValues = toP.map((targetVal, i) => {
        const fromVal = fromP[i] ?? 0;
        return fromVal + (targetVal - fromVal) * ease;
      });

      if (progress < 1) {
        needsNext = true;
      } else {
        dashboardChartState.isAnimating = false;
        dashboardChartState.currentSalesValues = [...dashboardChartState.targetSalesValues];
        dashboardChartState.currentPurchaseValues = [...dashboardChartState.targetPurchaseValues];
      }
    }

    if (dashboardChartState.isHovered) {
      if (dashboardChartState.hoverOpacity < 1) {
        dashboardChartState.hoverOpacity = Math.min(1, dashboardChartState.hoverOpacity + 0.16);
        needsNext = true;
      }
    } else {
      if (dashboardChartState.hoverOpacity > 0) {
        dashboardChartState.hoverOpacity = Math.max(0, dashboardChartState.hoverOpacity - 0.14);
        needsNext = true;
      }
    }

    renderChartCanvas();

    if (needsNext) {
      dashboardChartState.frameId = requestAnimationFrame(frame);
    }
  }

  dashboardChartState.frameId = requestAnimationFrame(frame);
}

function drawSmoothSpline(ctx, points, tension = 0.25) {
  if (!points || !points.length) return;
  if (points.length === 1) {
    ctx.moveTo(points[0].x, points[0].y);
    return;
  }
  if (points.length === 2) {
    ctx.moveTo(points[0].x, points[0].y);
    ctx.lineTo(points[1].x, points[1].y);
    return;
  }

  ctx.moveTo(points[0].x, points[0].y);

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = i > 0 ? points[i - 1] : points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = i < points.length - 2 ? points[i + 2] : p2;

    let cp1x = p1.x + (p2.x - p0.x) * tension;
    let cp1y = p1.y + (p2.y - p0.y) * tension;

    let cp2x = p2.x - (p3.x - p1.x) * tension;
    let cp2y = p2.y - (p3.y - p1.y) * tension;

    if (Math.abs(p1.y - p2.y) < 0.5) {
      cp1y = p1.y;
      cp2y = p2.y;
    }

    ctx.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, p2.x, p2.y);
  }
}

function renderChartCanvas() {
  const canvas = elements.salesChart;
  if (!canvas) return;

  const ctx = canvas.getContext("2d");
  const bounds = canvas.getBoundingClientRect();
  const width = Math.max(360, Math.floor(bounds.width || canvas.clientWidth || 920));
  const height = Math.max(200, Math.floor(bounds.height || canvas.clientHeight || 220));
  const dpr = Math.max(1, window.devicePixelRatio || 1);

  if (canvas.width !== Math.floor(width * dpr) || canvas.height !== Math.floor(height * dpr)) {
    canvas.width = Math.floor(width * dpr);
    canvas.height = Math.floor(height * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const pad = { top: 28, right: 28, bottom: 36, left: 56 };
  const plotWidth = width - pad.left - pad.right;
  const plotHeight = height - pad.top - pad.bottom;
  const baselineY = pad.top + plotHeight;

  const isAnim = dashboardChartState.isAnimating;
  const salesVals = isAnim && dashboardChartState.currentSalesValues.length ? dashboardChartState.currentSalesValues : dashboardChartState.targetSalesValues;
  const targetSales = dashboardChartState.targetSalesValues;
  const purchVals = isAnim && dashboardChartState.currentPurchaseValues.length ? dashboardChartState.currentPurchaseValues : dashboardChartState.targetPurchaseValues;
  const targetPurchases = dashboardChartState.targetPurchaseValues;
  const max = dashboardChartState.niceMax;
  const hasData = dashboardChartState.maxValue > 0;

  ctx.clearRect(0, 0, width, height);

  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, width, height);

  const steps = 4;
  ctx.font = "500 11px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
  ctx.textAlign = "right";

  for (let i = 0; i <= steps; i++) {
    const y = pad.top + (plotHeight / steps) * i;
    const gridVal = max - (max / steps) * i;

    ctx.beginPath();
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = i === steps ? "#cbd5e1" : "#f1f5f9";
    ctx.lineWidth = i === steps ? 1.25 : 1;
    ctx.moveTo(pad.left, y);
    ctx.lineTo(width - pad.right, y);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.fillStyle = "#94a3b8";
    const labelStr = compactNumber(gridVal);
    ctx.fillText(labelStr, pad.left - 10, y + 4);
  }

  const numPoints = Math.max(salesVals.length, purchVals.length);
  const salesPoints = salesVals.map((val, idx) => {
    const x = numPoints <= 1 ? pad.left + plotWidth / 2 : pad.left + (plotWidth / (numPoints - 1)) * idx;
    const y = baselineY - (Math.max(0, val) / max) * plotHeight;
    return { x, y, value: val, origVal: targetSales[idx] || 0 };
  });

  const purchasePoints = purchVals.map((val, idx) => {
    const x = numPoints <= 1 ? pad.left + plotWidth / 2 : pad.left + (plotWidth / (numPoints - 1)) * idx;
    const y = baselineY - (Math.max(0, val) / max) * plotHeight;
    return { x, y, value: val, origVal: targetPurchases[idx] || 0 };
  });

  const hasPurchases = targetPurchases.some((v) => v > 0);
  const hasSales = targetSales.some((v) => v > 0);

  if (hasData && numPoints > 1) {
    // 1. Draw Purchases Area & Spline first (underneath sales)
    if (hasPurchases) {
      ctx.save();
      ctx.beginPath();
      drawSmoothSpline(ctx, purchasePoints, 0.25);
      ctx.lineTo(purchasePoints[purchasePoints.length - 1].x, baselineY);
      ctx.lineTo(purchasePoints[0].x, baselineY);
      ctx.closePath();

      const gradientP = ctx.createLinearGradient(0, pad.top, 0, baselineY);
      gradientP.addColorStop(0, "rgba(245, 158, 11, 0.16)");
      gradientP.addColorStop(0.55, "rgba(245, 158, 11, 0.04)");
      gradientP.addColorStop(1, "rgba(245, 158, 11, 0.00)");
      ctx.fillStyle = gradientP;
      ctx.fill();
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      drawSmoothSpline(ctx, purchasePoints, 0.25);
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 2.5;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.shadowColor = "rgba(245, 158, 11, 0.26)";
      ctx.shadowBlur = 7;
      ctx.shadowOffsetY = 2;
      ctx.stroke();
      ctx.restore();

      purchasePoints.forEach((pt) => {
        if (pt.origVal <= 0) return;
        ctx.beginPath();
        ctx.arc(pt.x, pt.y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = "#ffffff";
        ctx.fill();
        ctx.strokeStyle = "#f59e0b";
        ctx.lineWidth = 2;
        ctx.stroke();
      });
    }

    // 2. Draw Sales Area & Spline
    if (hasSales) {
      ctx.save();
      ctx.beginPath();
      drawSmoothSpline(ctx, salesPoints, 0.25);
      ctx.lineTo(salesPoints[salesPoints.length - 1].x, baselineY);
      ctx.lineTo(salesPoints[0].x, baselineY);
      ctx.closePath();

      const gradientS = ctx.createLinearGradient(0, pad.top, 0, baselineY);
      gradientS.addColorStop(0, "rgba(12, 126, 232, 0.20)");
      gradientS.addColorStop(0.55, "rgba(12, 126, 232, 0.05)");
      gradientS.addColorStop(1, "rgba(12, 126, 232, 0.00)");
      ctx.fillStyle = gradientS;
      ctx.fill();
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      drawSmoothSpline(ctx, salesPoints, 0.25);
      ctx.strokeStyle = "#0c7ee8";
      ctx.lineWidth = 2.75;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.shadowColor = "rgba(12, 126, 232, 0.35)";
      ctx.shadowBlur = 8;
      ctx.shadowOffsetY = 3;
      ctx.stroke();
      ctx.restore();

      salesPoints.forEach((pt) => {
        if (pt.origVal <= 0) return;
        ctx.beginPath();
        ctx.arc(pt.x, pt.y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = "#ffffff";
        ctx.fill();
        ctx.strokeStyle = "#0c7ee8";
        ctx.lineWidth = 2;
        ctx.stroke();
      });
    }
  } else if (!hasData && numPoints > 1) {
    ctx.save();
    ctx.beginPath();
    ctx.setLineDash([5, 5]);
    ctx.moveTo(pad.left, baselineY);
    ctx.lineTo(width - pad.right, baselineY);
    ctx.strokeStyle = "rgba(148, 163, 184, 0.4)";
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();

    const cardW = Math.min(360, plotWidth - 40);
    const cardH = 54;
    const cardX = pad.left + (plotWidth - cardW) / 2;
    const cardY = pad.top + (plotHeight - cardH) / 2 - 4;

    ctx.save();
    ctx.fillStyle = "rgba(248, 250, 252, 0.95)";
    ctx.strokeStyle = "#e2e8f0";
    ctx.lineWidth = 1;
    ctx.shadowColor = "rgba(15, 23, 42, 0.04)";
    ctx.shadowBlur = 8;
    ctx.shadowOffsetY = 2;

    const r = 8;
    ctx.beginPath();
    ctx.moveTo(cardX + r, cardY);
    ctx.arcTo(cardX + cardW, cardY, cardX + cardW, cardY + cardH, r);
    ctx.arcTo(cardX + cardW, cardY + cardH, cardX, cardY + cardH, r);
    ctx.arcTo(cardX, cardY + cardH, cardX, cardY, r);
    ctx.arcTo(cardX, cardY, cardX + cardW, cardY, r);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.textAlign = "center";
    ctx.fillStyle = "#475569";
    ctx.font = "600 12.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText("No sales or purchases recorded for this period", cardX + cardW / 2, cardY + 23);

    ctx.fillStyle = "#94a3b8";
    ctx.font = "400 11px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText("Sales and purchase trends will animate here once transactions are recorded", cardX + cardW / 2, cardY + 41);
    ctx.restore();
  }

  // X-axis date/time labels
  const labels = dashboardChartState.labels;
  if (labels && labels.length) {
    const labelStep = Math.max(1, Math.ceil(labels.length / 10));
    ctx.textAlign = "center";
    ctx.fillStyle = "#94a3b8";
    ctx.font = "500 11px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";

    labels.forEach((label, index) => {
      if (index % labelStep !== 0 && index !== labels.length - 1) return;
      const x = salesPoints[index] ? salesPoints[index].x : pad.left + (plotWidth / (labels.length - 1)) * index;
      ctx.fillText(label, Math.max(pad.left, Math.min(width - pad.right, x)), baselineY + 18);
    });
  }

  // Canvas Title (top-left)
  ctx.textAlign = "left";
  ctx.fillStyle = "#334155";
  ctx.font = "600 13px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
  ctx.fillText(dashboardChartState.title, pad.left, 16);

  // Canvas Legend (top-right)
  ctx.save();
  ctx.textAlign = "right";
  ctx.font = "500 11px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
  const legendRight = width - pad.right;
  const legendY = 16;

  // Purchases indicator
  ctx.fillStyle = "#64748b";
  ctx.fillText("Purchases", legendRight, legendY);
  const purchTextW = ctx.measureText("Purchases").width;
  ctx.beginPath();
  ctx.arc(legendRight - purchTextW - 7, legendY - 3.5, 4, 0, Math.PI * 2);
  ctx.fillStyle = "#f59e0b";
  ctx.fill();

  // Sales indicator
  const salesTextRight = legendRight - purchTextW - 22;
  ctx.fillStyle = "#64748b";
  ctx.fillText("Sales", salesTextRight, legendY);
  const salesTextW = ctx.measureText("Sales").width;
  ctx.beginPath();
  ctx.arc(salesTextRight - salesTextW - 7, legendY - 3.5, 4, 0, Math.PI * 2);
  ctx.fillStyle = "#0c7ee8";
  ctx.fill();
  ctx.restore();

  // Hover Tooltip with Dual Values
  if (dashboardChartState.hoverOpacity > 0.01 && salesPoints.length > 0) {
    let closestIdx = 0;
    let minDist = Infinity;
    salesPoints.forEach((pt, i) => {
      const dist = Math.abs(pt.x - dashboardChartState.mouseX);
      if (dist < minDist) {
        minDist = dist;
        closestIdx = i;
      }
    });

    const activeSalePt = salesPoints[closestIdx] || { x: pad.left, y: baselineY, origVal: 0 };
    const activePurchPt = purchasePoints[closestIdx] || { x: pad.left, y: baselineY, origVal: 0 };
    const hoverAlpha = dashboardChartState.hoverOpacity;

    ctx.save();
    ctx.globalAlpha = hoverAlpha;

    // Vertical dashed guideline
    ctx.beginPath();
    ctx.setLineDash([4, 4]);
    ctx.moveTo(activeSalePt.x, pad.top);
    ctx.lineTo(activeSalePt.x, baselineY);
    ctx.strokeStyle = "rgba(148, 163, 184, 0.45)";
    ctx.lineWidth = 1.25;
    ctx.stroke();
    ctx.setLineDash([]);

    // Highlight dot on Purchase point
    if (activePurchPt.origVal > 0) {
      ctx.beginPath();
      ctx.arc(activePurchPt.x, activePurchPt.y, 8, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(245, 158, 11, 0.22)";
      ctx.fill();

      ctx.beginPath();
      ctx.arc(activePurchPt.x, activePurchPt.y, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 2.5;
      ctx.stroke();
    }

    // Highlight dot on Sale point
    if (activeSalePt.origVal > 0) {
      ctx.beginPath();
      ctx.arc(activeSalePt.x, activeSalePt.y, 8, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(12, 126, 232, 0.22)";
      ctx.fill();

      ctx.beginPath();
      ctx.arc(activeSalePt.x, activeSalePt.y, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = "#ffffff";
      ctx.fill();
      ctx.strokeStyle = "#0c7ee8";
      ctx.lineWidth = 2.5;
      ctx.stroke();
    }

    // Dual-item Tooltip Box
    const labelText = labels[closestIdx]
      ? `${labels[closestIdx]} ${dashboardChartState.activePeriod === "This Month" ? new Date().toLocaleString("en-IN", { month: "short" }) : ""}`.trim()
      : "";
    const saleVal = activeSalePt.origVal || 0;
    const purchVal = activePurchPt.origVal || 0;
    const saleText = `Sale: ${formatCurrency(saleVal)}`;
    const purchText = `Purchase: ${formatCurrency(purchVal)}`;

    ctx.font = "600 11px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    const titleWidth = ctx.measureText(labelText).width;
    ctx.font = "600 12px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    const saleWidth = ctx.measureText(saleText).width;
    const purchWidth = ctx.measureText(purchText).width;

    const maxTextW = Math.max(titleWidth, saleWidth, purchWidth);
    const tipW = Math.max(145, maxTextW + 30);
    const tipH = 68;

    let tipX = activeSalePt.x - tipW / 2;
    tipX = Math.max(pad.left + 4, Math.min(width - pad.right - tipW - 4, tipX));
    const highestY = Math.min(
      activeSalePt.origVal > 0 ? activeSalePt.y : baselineY,
      activePurchPt.origVal > 0 ? activePurchPt.y : baselineY
    );
    let tipY = highestY - tipH - 12;
    if (tipY < pad.top + 2) tipY = Math.max(activeSalePt.y, activePurchPt.y) + 14;
    if (tipY + tipH > baselineY) tipY = pad.top + 8;

    ctx.shadowColor = "rgba(15, 23, 42, 0.32)";
    ctx.shadowBlur = 12;
    ctx.shadowOffsetY = 4;
    ctx.fillStyle = "rgba(15, 23, 42, 0.94)";
    ctx.strokeStyle = "rgba(255, 255, 255, 0.12)";
    ctx.lineWidth = 1;

    const tr = 7;
    ctx.beginPath();
    ctx.moveTo(tipX + tr, tipY);
    ctx.arcTo(tipX + tipW, tipY, tipX + tipW, tipY + tipH, tr);
    ctx.arcTo(tipX + tipW, tipY + tipH, tipX, tipY + tipH, tr);
    ctx.arcTo(tipX, tipY + tipH, tipX, tipY, tr);
    ctx.arcTo(tipX, tipY, tipX + tipW, tipY, tr);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.shadowColor = "transparent";

    // Header date
    ctx.textAlign = "left";
    ctx.fillStyle = "#94a3b8";
    ctx.font = "600 11px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText(labelText, tipX + 12, tipY + 16);

    // Subtle divider
    ctx.beginPath();
    ctx.moveTo(tipX + 12, tipY + 22);
    ctx.lineTo(tipX + tipW - 12, tipY + 22);
    ctx.strokeStyle = "rgba(255, 255, 255, 0.08)";
    ctx.lineWidth = 1;
    ctx.stroke();

    // Sale row
    ctx.beginPath();
    ctx.arc(tipX + 16, tipY + 36, 3.5, 0, Math.PI * 2);
    ctx.fillStyle = "#38bdf8";
    ctx.fill();

    ctx.fillStyle = "#e2e8f0";
    ctx.font = "500 11.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText("Sale:", tipX + 25, tipY + 39);

    ctx.fillStyle = saleVal > 0 ? "#38bdf8" : "#94a3b8";
    ctx.font = "700 11.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.textAlign = "right";
    ctx.fillText(formatCurrency(saleVal), tipX + tipW - 12, tipY + 39);

    // Purchase row
    ctx.textAlign = "left";
    ctx.beginPath();
    ctx.arc(tipX + 16, tipY + 54, 3.5, 0, Math.PI * 2);
    ctx.fillStyle = "#fbbf24";
    ctx.fill();

    ctx.fillStyle = "#e2e8f0";
    ctx.font = "500 11.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText("Purchase:", tipX + 25, tipY + 57);

    ctx.fillStyle = purchVal > 0 ? "#fbbf24" : "#94a3b8";
    ctx.font = "700 11.5px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.textAlign = "right";
    ctx.fillText(formatCurrency(purchVal), tipX + tipW - 12, tipY + 57);

    ctx.restore();
  }
}

function dashboardSeries(period) {
  const now = new Date();
  const sales = invoiceRowsForType("sale")
    .filter((entry) => invoiceStatusKey(entry) !== "cancelled")
    .map((entry) => ({ entry, date: dashboardEntryDate(entry), amount: invoiceTotalValue(entry) }))
    .filter((row) => row.date && Number.isFinite(row.amount));

  const purchases = invoiceRowsForType("purchase")
    .filter((entry) => invoiceStatusKey(entry) !== "cancelled")
    .map((entry) => ({ entry, date: dashboardEntryDate(entry), amount: invoiceTotalValue(entry) }))
    .filter((row) => row.date && Number.isFinite(row.amount));

  if (period === "Today") {
    const labels = ["12 AM", "3 AM", "6 AM", "9 AM", "12 PM", "3 PM", "6 PM", "9 PM"];
    const salesValues = Array(labels.length).fill(0);
    const purchaseValues = Array(labels.length).fill(0);
    sales.forEach((row) => {
      if (!sameDate(row.date, now)) return;
      const index = Math.min(labels.length - 1, Math.floor(row.date.getHours() / 3));
      salesValues[index] += row.amount;
    });
    purchases.forEach((row) => {
      if (!sameDate(row.date, now)) return;
      const index = Math.min(labels.length - 1, Math.floor(row.date.getHours() / 3));
      purchaseValues[index] += row.amount;
    });
    return {
      title: "Sales & Purchases Today",
      labels,
      salesValues,
      purchaseValues,
      values: salesValues,
    };
  }

  if (period === "This Year") {
    const labels = Array.from({ length: 12 }, (_, index) => new Date(now.getFullYear(), index, 1).toLocaleString("en-IN", { month: "short" }));
    const salesValues = Array(12).fill(0);
    const purchaseValues = Array(12).fill(0);
    sales.forEach((row) => {
      if (row.date.getFullYear() !== now.getFullYear()) return;
      salesValues[row.date.getMonth()] += row.amount;
    });
    purchases.forEach((row) => {
      if (row.date.getFullYear() !== now.getFullYear()) return;
      purchaseValues[row.date.getMonth()] += row.amount;
    });
    return {
      title: `Sales & Purchases in ${now.getFullYear()}`,
      labels,
      salesValues,
      purchaseValues,
      values: salesValues,
    };
  }

  const year = now.getFullYear();
  const month = now.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const labels = Array.from({ length: daysInMonth }, (_, index) => String(index + 1));
  const salesValues = Array(daysInMonth).fill(0);
  const purchaseValues = Array(daysInMonth).fill(0);
  sales.forEach((row) => {
    if (row.date.getFullYear() !== year || row.date.getMonth() !== month) return;
    salesValues[row.date.getDate() - 1] += row.amount;
  });
  purchases.forEach((row) => {
    if (row.date.getFullYear() !== year || row.date.getMonth() !== month) return;
    purchaseValues[row.date.getDate() - 1] += row.amount;
  });
  return {
    title: `Sales & Purchases in ${now.toLocaleString("en-IN", { month: "long", year: "numeric" })}`,
    labels,
    salesValues,
    purchaseValues,
    values: salesValues,
  };
}

function dashboardSalesSeries(period) {
  return dashboardSeries(period);
}

function dashboardEntryDate(entry) {
  return parseEditorDateAsDate(entry.date || entry.invoiceDate || entry.createdAt);
}

function sameDate(left, right) {
  return left.getFullYear() === right.getFullYear()
    && left.getMonth() === right.getMonth()
    && left.getDate() === right.getDate();
}

function niceChartMax(value) {
  if (!value || value <= 0) return 1;
  const power = 10 ** Math.floor(Math.log10(value));
  const normalized = value / power;
  const nice = normalized <= 2 ? 2 : normalized <= 5 ? 5 : 10;
  return nice * power;
}

function compactNumber(value) {
  return new Intl.NumberFormat("en-IN", {
    notation: Math.abs(value) >= 10000 ? "compact" : "standard",
    maximumFractionDigits: value >= 10 ? 0 : 1,
  }).format(Number(value || 0));
}

function totalFor(type) {
  return activeInvoiceRowsForType(type).reduce((sum, entry) => sum + invoiceTotalValue(entry), 0);
}

function totalReceivable() {
  return invoiceRowsForType("sale")
    .filter((entry) => invoiceStatusKey(entry) !== "cancelled")
    .reduce((total, entry) => total + invoiceBalanceValue(entry), 0);
}

function totalPayable() {
  return invoiceRowsForType("purchase")
    .filter((entry) => invoiceStatusKey(entry) !== "cancelled")
    .reduce((total, entry) => total + invoiceBalanceValue(entry), 0);
}

function sumAmount(total, entry) {
  return total + Number(entry.amount ?? entry.total ?? 0);
}

function formatCurrency(value) {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    maximumFractionDigits: 0,
  }).format(Number(value || 0));
}

function formatQuantity(value) {
  return new Intl.NumberFormat("en-IN", {
    maximumFractionDigits: 2,
  }).format(Number(value || 0));
}

function formatDate(value) {
  if (!value) return "-";
  return new Intl.DateTimeFormat("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(new Date(value));
}

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => {
    return {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#039;",
    }[char];
  });
}

function icon(name, className = "") {
  const safeName = String(name || "").replace(/[^a-z0-9-]/gi, "");
  const safeClass = String(className || "").replace(/[^a-z0-9-_ ]/gi, "");
  return `<svg class="gi-icon${safeClass ? ` ${safeClass}` : ""}" aria-hidden="true"><use href="#gi-${safeName}"></use></svg>`;
}

// ── Payment-In Module ─────────────────────────────────────────────────────────

function paymentInTemplate() {
  const payments = (state.payments || [])
    .filter((p) => p.type === "payment_in")
    .sort((a, b) => new Date(b.paymentDate || b.createdAt || 0) - new Date(a.paymentDate || a.createdAt || 0));
  const receivable = totalReceivable();
  const now = new Date();
  const thisMonthPayments = payments.filter((p) => {
    const d = new Date(p.paymentDate || p.createdAt || "");
    return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();
  });
  const thisMonthTotal = thisMonthPayments.reduce((sum, p) => sum + Number(p.amount || 0), 0);
  const totalReceived  = payments.reduce((s, p) => s + Number(p.amount || 0), 0);

  const searchQ = String(reportSearchQuery || "").trim().toLowerCase();
  const visible  = searchQ
    ? payments.filter((p) => [p.party, p.invoiceNo, p.referenceNo, p.method, p.notes].filter(Boolean).join(" ").toLowerCase().includes(searchQ))
    : payments;

  return `
    <section class="invoice-workspace sale-workspace">
      <header class="app-page-header invoice-page-header">
        <div>
          <p class="muted-label">Sales</p>
          <h1>Payment-In</h1>
          <small>${payments.length} payment${payments.length === 1 ? "" : "s"} recorded</small>
        </div>
        <div class="invoice-header-actions">
          <button class="sale-button" data-action="create-payment-in" type="button">+ Record Payment</button>
        </div>
      </header>

      <section class="kpi-grid invoice-kpis">
        ${kpiCard("This Month", formatCurrency(thisMonthTotal), `${thisMonthPayments.length} payment${thisMonthPayments.length === 1 ? "" : "s"} received`, "success")}
        ${kpiCard("Total Received", formatCurrency(totalReceived), "All time", "neutral")}
        ${kpiCard("Receivable", formatCurrency(receivable), "Pending customer balances", receivable > 0 ? "danger" : "success")}
        ${kpiCard("Payments", String(payments.length), "All recorded", "info")}
      </section>

      <section class="app-toolbar" style="padding:8px 0 4px;">
        <label class="toolbar-search">
          <span>Search</span>
          <input class="form-input" data-payment-in-search type="search"
            value="${escapeHtml(reportSearchQuery)}"
            placeholder="Customer, invoice ref, method, notes">
        </label>
      </section>

      <section class="data-table-card invoice-data-card">
        ${visible.length ? `
          <table class="data-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Customer</th>
                <th>Invoice Ref</th>
                <th>Method</th>
                <th class="num">Amount</th>
                <th>Notes</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              ${visible.map((p) => `
                <tr>
                  <td>${formatDate(p.paymentDate || p.createdAt)}</td>
                  <td><strong>${escapeHtml(p.party || "-")}</strong></td>
                  <td>${escapeHtml(p.invoiceNo || p.referenceNo || "-")}</td>
                  <td><span class="status-badge">${escapeHtml(p.method || "Cash")}</span></td>
                  <td class="num amount-cell strong">${formatCurrency(p.amount || 0)}</td>
                  <td class="muted-text">${escapeHtml(p.notes || "-")}</td>
                  <td>
                    <details class="invoice-row-details">
                      <summary>⋮</summary>
                      <div class="invoice-action-menu">
                        <section>
                          <span>Actions</span>
                          <button type="button" data-payment-in-action="delete" data-payment-id="${escapeHtml(String(p.id || ""))}">Delete</button>
                        </section>
                      </div>
                    </details>
                  </td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        ` : `
          <div class="feature-empty-card">
            <strong>${searchQ ? "No matching payments" : "No payments recorded yet"}</strong>
            <p>${searchQ ? "Try a different customer name, method, or invoice reference." : "Record incoming payments from customers against sale invoices."}</p>
            ${!searchQ ? `<button class="sale-button" data-action="create-payment-in" type="button">+ Record Payment</button>` : ""}
          </div>
        `}
      </section>
    </section>
  `;
}

function openPaymentInModal() {
  const invoices = activeInvoiceRowsForType("sale").filter((inv) => invoiceBalanceValue(inv) > 0);
  const customers = (state.parties || []).filter((p) => p.type === "customer" || p.type === "both");
  const existingModal = document.getElementById("paymentInModal");
  if (existingModal) existingModal.remove();
  const modal = document.createElement("div");
  modal.className = "modal-backdrop";
  modal.id = "paymentInModal";
  modal.innerHTML = `
    <section class="entry-modal payment-modal-shell" role="dialog" aria-modal="true" aria-labelledby="paymentInTitle">
      <header class="entry-modal-header">
        <div class="entry-modal-title-wrap">
          <span class="entry-modal-icon payment-in-icon">
            <svg class="gi-icon"><use href="#gi-arrow-down"></use></svg>
          </span>
          <div>
            <h2 id="paymentInTitle">Record Payment-In</h2>
            <p class="entry-modal-subtitle">Record money received from a customer for invoices or advances</p>
          </div>
        </div>
        <button class="close-button" type="button" data-close-payment-modal title="Close">&times;</button>
      </header>
      <form id="paymentInForm" class="payment-entry-form" novalidate>
        <div class="payment-modal-body">
          <div class="payment-form-grid">
            <div class="party-field-group full-width">
              <label class="field-label">Customer <span class="req">*</span></label>
              <input class="form-input" name="party" list="paymentPartyList" placeholder="Select or enter customer name" autocomplete="off" required>
              <datalist id="paymentPartyList">
                ${(customers.length ? customers : state.parties || []).map((p) => `<option value="${escapeHtml(p.name)}">`).join("")}
              </datalist>
            </div>

            <div class="party-field-group full-width">
              <label class="field-label">Invoice Reference</label>
              <select class="form-input" name="invoiceRef">
                <option value="">— Select invoice (optional) —</option>
                ${invoices.map((inv) => `<option value="${escapeHtml(inv.invoiceNo || inv.id)}" data-party="${escapeHtml(inv.party)}" data-balance="${invoiceBalanceValue(inv)}">${escapeHtml(inv.invoiceNo || inv.id)} — ${escapeHtml(inv.party)} — Due: ${formatCurrency(invoiceBalanceValue(inv))}</option>`).join("")}
              </select>
            </div>

            <div class="party-field-group">
              <label class="field-label">Amount (₹) <span class="req">*</span></label>
              <div class="input-with-prefix">
                <span class="prefix">₹</span>
                <input class="form-input" name="amount" type="number" step="0.01" min="0.01" placeholder="0.00" required>
              </div>
            </div>

            <div class="party-field-group">
              <label class="field-label">Payment Date</label>
              <input class="form-input" name="paymentDate" type="date" value="${new Date().toISOString().slice(0, 10)}">
            </div>

            <div class="party-field-group">
              <label class="field-label">Payment Method</label>
              <select class="form-input" name="method">
                ${editorPaymentMethodOptions(false)}
              </select>
            </div>

            <div class="party-field-group">
              <label class="field-label">Notes / Remarks</label>
              <input class="form-input" name="notes" placeholder="Reference number, cheque no, etc.">
            </div>
          </div>
        </div>
        <footer class="entry-modal-footer">
          <div class="entry-modal-footer-left">
            <span id="paymentInStatus"></span>
          </div>
          <div class="entry-modal-footer-right">
            <button class="secondary-button" type="button" data-close-payment-modal>Cancel</button>
            <button class="primary-button payment-in-submit-btn" type="submit">Save Payment</button>
          </div>
        </footer>
      </form>
    </section>
  `;
  document.body.append(modal);

  const selectEl = modal.querySelector('[name="invoiceRef"]');
  const partyInput = modal.querySelector('[name="party"]');
  const amountInput = modal.querySelector('[name="amount"]');
  selectEl?.addEventListener("change", () => {
    const opt = selectEl.selectedOptions[0];
    if (opt?.dataset.party) {
      partyInput.value = opt.dataset.party;
    }
    if (opt?.dataset.balance && !amountInput.value) {
      amountInput.value = opt.dataset.balance;
    }
  });

  const closeModal = () => {
    modal.remove();
    window.removeEventListener("keydown", handleEscape);
  };
  const handleEscape = (e) => {
    if (e.key === "Escape") closeModal();
  };
  window.addEventListener("keydown", handleEscape);

  modal.querySelectorAll("[data-close-payment-modal]").forEach((btn) => {
    btn.addEventListener("click", closeModal);
  });
  modal.addEventListener("click", (e) => { if (e.target === modal) closeModal(); });
  modal.querySelector("#paymentInForm")?.addEventListener("submit", async (e) => {
    e.preventDefault();
    const form = new FormData(e.currentTarget);
    const amount = Number(form.get("amount") || 0);
    let party = String(form.get("party") || "").trim();
    if (!amount || amount <= 0) {
      showToast("Please enter a valid amount.");
      return;
    }
    const payment = {
      type: "payment_in",
      party,
      invoiceNo: String(form.get("invoiceRef") || ""),
      referenceNo: String(form.get("invoiceRef") || ""),
      amount,
      paymentDate: String(form.get("paymentDate") || new Date().toISOString().slice(0, 10)),
      method: String(form.get("method") || "Cash"),
      notes: String(form.get("notes") || "").trim(),
      createdAt: new Date().toISOString(),
    };
    try {
      if (window.giDB?.recordPaymentIn) {
        const invoiceRef = form.get("invoiceRef");
        let invoiceId = null;
        if (invoiceRef) {
          const invoice = findInvoiceRecord(invoiceRef) || activeInvoiceRowsForType("sale").find((inv) => inv.invoiceNo === invoiceRef || inv.id === invoiceRef);
          if (invoice) {
            invoiceId = invoice.id || invoice.invoiceId;
            if (!party) party = invoice.party;
          }
        }
        if (!invoiceId && !party) {
          showToast("Please enter a customer name or select an invoice.");
          return;
        }
        state = normalizeState(await window.giDB.recordPaymentIn({
          invoiceId,
          party,
          amount,
          method: payment.method,
          notes: payment.notes,
          paymentDate: payment.paymentDate,
        }));
      } else if (window.giDB?.recordInvoicePayment) {
        const invoiceRef = form.get("invoiceRef");
        if (invoiceRef) {
          const invoice = findInvoiceRecord(invoiceRef) || activeInvoiceRowsForType("sale").find((inv) => inv.invoiceNo === invoiceRef);
          if (invoice) {
            state = normalizeState(await window.giDB.recordInvoicePayment({ invoiceId: invoice.id || invoice.invoiceId, amount, method: payment.method, notes: payment.notes, paymentDate: payment.paymentDate }));
          }
        }
      } else {
        state.payments = [payment, ...(state.payments || [])];
        saveState();
      }
      modal.remove();
      showToast("Payment recorded.");
      renderDashboard();
      renderFeatureView("paymentIn");
    } catch (err) {
      const status = modal.querySelector("#paymentInStatus");
      if (status) status.textContent = err.message || "Unable to record payment.";
    }
  });
}

// ── CSV Import Module ─────────────────────────────────────────────────────────

let csvImportRows = [];
let csvImportType = "items";

function csvImportTemplate(importType = "items") {
  csvImportType = importType;
  const isItems = importType === "items";
  const title = isItems ? "Import Items" : "Import Parties";
  const templateHeaders = isItems
    ? ["Name", "SKU", "Category", "Unit", "HSN Code", "Sale Price", "Purchase Price", "Tax Rate", "Opening Stock"]
    : ["Name", "Phone", "Email", "GSTIN", "State", "Billing Address", "Opening Balance"];

  return `
    <section class="feature-page" data-import-type="${importType}">
      <header class="app-page-header">
        <div>
          <p class="muted-label">Utilities</p>
          <h1>${title}</h1>
          <small>Upload a CSV file to bulk import</small>
        </div>
        <div class="invoice-header-actions">
          <button class="secondary-button" data-action="csv-import-export-template" type="button">Download Template</button>
        </div>
      </header>
      <section class="data-table-card" style="padding:2rem;margin:1rem 0;">
        <h3>Step 1 — Choose CSV File</h3>
        <p style="margin:.5rem 0 1rem;color:var(--text-muted)">CSV must have headers: <code>${templateHeaders.join(", ")}</code></p>
        <label class="secondary-button" for="csvFileInput" style="display:inline-block;cursor:pointer;">Choose File</label>
        <input type="file" id="csvFileInput" accept=".csv,text/csv" style="display:none">
        <span id="csvFileName" style="margin-left:1rem;color:var(--text-muted)">No file chosen</span>
      </section>
      <section id="csvPreviewSection" class="data-table-card" style="padding:2rem;margin:1rem 0;display:none;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;">
          <h3>Step 2 — Preview &amp; Import</h3>
          <button class="sale-button" data-action="csv-import-run" type="button">Import All Rows</button>
        </div>
        <div id="csvPreviewTable"></div>
      </section>
    </section>
  `;
}

function handleCsvFileSelected(input) {
  const file = input.files[0];
  const nameSpan = elements.featureView.querySelector("#csvFileName");
  const previewSection = elements.featureView.querySelector("#csvPreviewSection");
  if (nameSpan) nameSpan.textContent = file ? file.name : "No file chosen";
  if (!file) { if (previewSection) previewSection.style.display = "none"; return; }
  const reader = new FileReader();
  reader.onload = (e) => {
    const text = e.target.result;
    csvImportRows = parseCsv(text);
    renderCsvPreview();
  };
  reader.readAsText(file);
}

function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) return [];
  const headers = lines[0].split(",").map((h) => h.trim().replace(/^"|"$/g, ""));
  return lines.slice(1).map((line) => {
    const values = line.split(",").map((v) => v.trim().replace(/^"|"$/g, ""));
    const row = {};
    headers.forEach((header, i) => { row[header] = values[i] || ""; });
    return row;
  }).filter((row) => Object.values(row).some(Boolean));
}

function renderCsvPreview() {
  const previewSection = elements.featureView.querySelector("#csvPreviewSection");
  const previewTable = elements.featureView.querySelector("#csvPreviewTable");
  if (!previewSection || !previewTable) return;
  if (!csvImportRows.length) {
    previewTable.innerHTML = "<p>No rows found in CSV.</p>";
    previewSection.style.display = "";
    return;
  }
  const headers = Object.keys(csvImportRows[0]);
  previewTable.innerHTML = `
    <table class="data-table">
      <thead><tr>${headers.map((h) => `<th>${escapeHtml(h)}</th>`).join("")}</tr></thead>
      <tbody>
        ${csvImportRows.slice(0, 20).map((row) => `<tr>${headers.map((h) => `<td>${escapeHtml(row[h] || "")}</td>`).join("")}</tr>`).join("")}
      </tbody>
    </table>
    ${csvImportRows.length > 20 ? `<p style="margin-top:.5rem;color:var(--text-muted)">Showing 20 of ${csvImportRows.length} rows</p>` : ""}
    <p style="margin-top:1rem;"><strong>${csvImportRows.length} row${csvImportRows.length === 1 ? "" : "s"}</strong> ready to import.</p>
  `;
  previewSection.style.display = "";
}

async function runCsvImport() {
  if (!csvImportRows.length) { showToast("No rows to import."); return; }
  const isItems = csvImportType === "items";
  let success = 0;
  let errors = 0;
  let warnings = [];
  let errorDetails = [];
  for (let index = 0; index < csvImportRows.length; index++) {
    const row = csvImportRows[index];
    const name = (row["Name"] || row["name"] || "").trim();
    if (!name) {
      errors++;
      errorDetails.push(`Row ${index + 1}: Name is required`);
      continue;
    }
    try {
      if (isItems) {
        const rawCategory = (row["Category"] || row["category"] || "").trim();
        const rawUnit = (row["Unit"] || row["unit"] || "Pcs").trim();

        let categoryName = rawCategory;
        let unitName = rawUnit;

        if (categoryName && window.giDB) {
          const existingCat = (state.itemCategories || []).find((c) => c.name.toLowerCase() === categoryName.toLowerCase());
          if (!existingCat) {
            try {
              state = normalizeState(await window.giDB.createItemCategory({ name: categoryName }));
              warnings.push(`Created category "${categoryName}".`);
            } catch (_) { /* category may already exist from parallel import */ }
          }
        }
        if (unitName && window.giDB) {
          const existingUnit = (state.units || []).find((u) => u.name.toLowerCase() === unitName.toLowerCase());
          if (!existingUnit) {
            try {
              state = normalizeState(await window.giDB.createUnit({ name: unitName }));
              warnings.push(`Created unit "${unitName}".`);
            } catch (_) { /* unit may already exist from parallel import */ }
          }
        }

        const itemDetails = {
          name,
          sku: row["SKU"] || row["sku"] || "",
          category: categoryName,
          unit: unitName,
          hsnSac: row["HSN Code"] || row["HSN/SAC"] || "",
          salePrice: Number(row["Sale Price"] || row["salePrice"] || 0),
          purchasePrice: Number(row["Purchase Price"] || row["purchasePrice"] || 0),
          taxRate: Number(row["Tax Rate"] || row["taxRate"] || 0),
          openingStock: Number(row["Opening Stock"] || row["openingStock"] || 0),
          currentStock: Number(row["Opening Stock"] || row["openingStock"] || 0),
          itemType: "product",
          notes: "",
        };
        if (window.giDB?.createItem) {
          state = normalizeState(await window.giDB.createItem(itemDetails));
        } else {
          if (!state.items.some((item) => item.name.toLowerCase() === name.toLowerCase())) {
            state.items.unshift({ ...itemDetails, id: Date.now() + Math.random(), createdAt: new Date().toISOString() });
          }
        }
      } else {
        const partyDetails = {
          name,
          phone: row["Phone"] || row["phone"] || "",
          email: row["Email"] || row["email"] || "",
          gstin: row["GSTIN"] || row["gstin"] || "",
          state: row["State"] || row["state"] || "",
          billingAddress: row["Billing Address"] || row["billingAddress"] || "",
          openingBalance: Number(row["Opening Balance"] || row["openingBalance"] || 0),
          type: "party",
          taxType: row["GSTIN"] ? "gst_registered" : "unregistered",
          notes: "",
        };
        if (window.giDB?.createParty) {
          state = normalizeState(await window.giDB.createParty(partyDetails));
        } else {
          if (!state.parties.some((p) => p.name.toLowerCase() === name.toLowerCase())) {
            state.parties.unshift({ ...partyDetails, id: Date.now() + Math.random(), createdAt: new Date().toISOString() });
          }
        }
      }
      success++;
    } catch (err) {
      errors++;
      errorDetails.push(`Row ${index + 1} ("${name}"): ${err.message || "Failed to save"}`);
    }
  }
  if (!window.giDB) saveState();
  csvImportRows = [];
  const warnText = warnings.length ? ` (${warnings.slice(0, 3).join("; ")}${warnings.length > 3 ? "..." : ""})` : "";
  const errorSummary = errorDetails.length ? ` (${errorDetails.slice(0, 2).join("; ")}${errorDetails.length > 2 ? ` +${errorDetails.length - 2} more` : ""})` : "";
  showToast(`Import complete: ${success} added${errors ? `, ${errors} skipped${errorSummary}` : ""}${warnText}.`);
  renderFeatureView(csvImportType === "items" ? "importItems" : "importParties");
}

function exportCsvTemplate(importType = "items") {
  const headers = importType === "items"
    ? ["Name", "SKU", "Category", "Unit", "HSN Code", "Sale Price", "Purchase Price", "Tax Rate", "Opening Stock"]
    : ["Name", "Phone", "Email", "GSTIN", "State", "Billing Address", "Opening Balance"];
  const sampleRow = importType === "items"
    ? ["Sample Item", "SKU001", "Electronics", "Pcs", "8471", "1000", "800", "18", "100"]
    : ["Sample Customer", "9876543210", "customer@example.com", "22AAAAA0000A1Z5", "Karnataka", "123 Main Street", "5000"];
  const csv = [headers.join(","), sampleRow.join(",")].join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${importType}_import_template.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast("Template downloaded.");
}

// ── Sale Order / Delivery Challan ─────────────────────────────────────────────
// Both are served by estimateTemplate() which reads currentView and adapts
// labels, KPI headings, empty-state copy, and action menu text automatically.
// Records are stored in state.estimates[] with documentType "sale_order" /
// "delivery_challan" respectively. Do NOT add separate template functions here.

function openKeyboardShortcutsDialog() {
  const existing = document.querySelector(".shortcuts-backdrop");
  if (existing) existing.remove();

  const backdrop = document.createElement("div");
  backdrop.className = "modal-backdrop shortcuts-backdrop";
  backdrop.innerHTML = `
    <section class="shortcuts-dialog" role="dialog" aria-modal="true" aria-label="Keyboard Shortcuts">
      <header>
        <strong>Keyboard Shortcuts</strong>
        <button class="close-button" type="button" data-close-shortcuts>&times;</button>
      </header>
      <div class="shortcuts-body">
        <div class="shortcuts-group">
          <h4>General</h4>
          <div class="shortcut-row"><span>Open Anything / Search</span><kbd>Ctrl</kbd><kbd>/</kbd></div>
          <div class="shortcut-row"><span>Dashboard / Home</span><kbd>Ctrl</kbd><kbd>H</kbd></div>
          <div class="shortcut-row"><span>Refresh</span><kbd>Ctrl</kbd><kbd>R</kbd></div>
          <div class="shortcut-row"><span>Close / Cancel</span><kbd>Esc</kbd></div>
        </div>
        <div class="shortcuts-group">
          <h4>Sales &amp; Invoices</h4>
          <div class="shortcut-row"><span>New Sale Invoice</span><kbd>Ctrl</kbd><kbd>N</kbd></div>
          <div class="shortcut-row"><span>Save Sale</span><kbd>Ctrl</kbd><kbd>S</kbd></div>
          <div class="shortcut-row"><span>Save &amp; Print</span><kbd>Ctrl</kbd><kbd>P</kbd></div>
          <div class="shortcut-row"><span>Save &amp; Submit</span><kbd>Ctrl</kbd><kbd>Enter</kbd></div>
          <div class="shortcut-row"><span>Add New Row</span><kbd>Alt</kbd><kbd>R</kbd></div>
          <div class="shortcut-row"><span>Move to Next Field</span><kbd>Enter</kbd></div>
        </div>
      </div>
      <footer>
        <button class="primary-button square" type="button" data-close-shortcuts>Done</button>
      </footer>
    </section>
  `;
  document.body.append(backdrop);

  const close = () => backdrop.remove();
  backdrop.querySelectorAll("[data-close-shortcuts]").forEach((btn) => btn.addEventListener("click", close));
  backdrop.addEventListener("click", (e) => { if (e.target === backdrop) close(); });
  document.addEventListener("keydown", function handler(e) {
    if (e.key === "Escape") {
      document.removeEventListener("keydown", handler);
      close();
    }
  });
}
